function generateAssessmentPrompt(hostname, username) {
    return `We have the following OSCAL Artifacts:
    Catalog:
        /tmp/data/catalog-new.json
    Component Definitions:
        /tmp/data/component-software.json
        /tmp/data/component-validation-agent.json
        /tmp/data/component-validation-oscap.json

We want you to assess our target RHEL system. You can use the following credentials.
    hostname: ${hostname}
    username: ${username}
    path to sshkey: /tmp/ssh_ciso_agent

Given the validation component definition (with the validator set as "agent") and the credentials specifying the target system,
please perform an assessment on the target environment and produce an OSCAL Assessment Results file as output.

Please just perform assessment.`;
};

$assessment_agent_goal = generateAssessmentPrompt($target_hostname, $target_username)
